namespace StormPT.MobileLab;

/// <summary>
/// LAB-only mapping between TWO INDEPENDENT runtime entity namespaces.
///
/// Native StormPT: dwObjectSerial (uint32, generated by the server).
/// PTM/NFMsg: Ident(svrid,index), two int64 fields.
///
/// The mapping is NOT arithmetic. It is populated exclusively by a future
/// trusted server-side adapter after it has verified account, character,
/// session and the relevant native/mobile spawn events. NO HTTP endpoint is
/// implemented here. It is not proof of login or authorization.
/// </summary>
internal readonly record struct NativeRuntimeEntity(Guid ServerEpoch, uint ObjectSerial);
internal readonly record struct MobileRuntimeEntity(long ServerId, long Index);

internal sealed record LabEntityBinding(
    string Account, string Character, string SessionKey,
    NativeRuntimeEntity Native, MobileRuntimeEntity Mobile);

internal enum BindOutcome { Created, AlreadyBound, Conflict, Invalid }

internal sealed class LabIdentityCrosswalk
{
    private readonly object _sync = new();
    private Guid _serverEpoch;
    private readonly Dictionary<uint, LabEntityBinding> _byNative = new();
    private readonly Dictionary<MobileRuntimeEntity, LabEntityBinding> _byMobile = new();
    private readonly Dictionary<string, LabEntityBinding> _bySession =
        new(StringComparer.Ordinal);

    internal LabIdentityCrosswalk(Guid serverEpoch)
    {
        if (serverEpoch == Guid.Empty) throw new ArgumentException("Epoch required.");
        _serverEpoch = serverEpoch;
    }

    internal BindOutcome BindVerified(LabEntityBinding binding)
    {
        ArgumentNullException.ThrowIfNull(binding);
        if (binding.Native.ServerEpoch == Guid.Empty ||
            binding.Native.ObjectSerial == 0 ||
            binding.Mobile.ServerId < 0 ||
            binding.Mobile.Index <= 0 ||
            string.IsNullOrWhiteSpace(binding.SessionKey) ||
            string.IsNullOrWhiteSpace(binding.Account) ||
            string.IsNullOrWhiteSpace(binding.Character))
            return BindOutcome.Invalid;

        lock (_sync)
        {
            if (binding.Native.ServerEpoch != _serverEpoch)
                return BindOutcome.Invalid; // A boot/restart changes the native IDs.

            _byNative.TryGetValue(binding.Native.ObjectSerial, out var native);
            _byMobile.TryGetValue(binding.Mobile, out var mobile);
            _bySession.TryGetValue(binding.SessionKey, out var session);

            if (native is not null || mobile is not null || session is not null)
                return (native == binding && mobile == binding && session == binding)
                    ? BindOutcome.AlreadyBound
                    : BindOutcome.Conflict;

            _byNative.Add(binding.Native.ObjectSerial, binding);
            _byMobile.Add(binding.Mobile, binding);
            _bySession.Add(binding.SessionKey, binding);
            return BindOutcome.Created;
        }
    }

    /// <summary>
    /// Resolution requires BOTH runtime epoch and server-authenticated session.
    /// Knowledge of a serial or Mobile Ident alone cannot retrieve a binding.
    /// </summary>
    internal bool TryResolveNative(
        Guid serverEpoch, string verifiedSessionKey, uint nativeSerial,
        out MobileRuntimeEntity mobile)
    {
        mobile = default;
        lock (_sync)
        {
            if (serverEpoch != _serverEpoch ||
                string.IsNullOrEmpty(verifiedSessionKey) ||
                !_byNative.TryGetValue(nativeSerial, out var found) ||
                !string.Equals(found.SessionKey, verifiedSessionKey,
                    StringComparison.Ordinal))
                return false;
            mobile = found.Mobile;
            return true;
        }
    }

    internal bool TryResolveMobile(
        Guid serverEpoch, string verifiedSessionKey, MobileRuntimeEntity mobile,
        out uint nativeSerial)
    {
        nativeSerial = 0;
        lock (_sync)
        {
            if (serverEpoch != _serverEpoch ||
                string.IsNullOrEmpty(verifiedSessionKey) ||
                !_byMobile.TryGetValue(mobile, out var found) ||
                !string.Equals(found.SessionKey, verifiedSessionKey,
                    StringComparison.Ordinal))
                return false;
            nativeSerial = found.Native.ObjectSerial;
            return true;
        }
    }

    /// <summary>Invalidate a mapping on logout, disconnect, despawn or revoke.</summary>
    internal bool ForgetVerifiedSession(string sessionKey)
    {
        lock (_sync)
        {
            if (!_bySession.Remove(sessionKey, out var entry)) return false;
            _byNative.Remove(entry.Native.ObjectSerial);
            _byMobile.Remove(entry.Mobile);
            return true;
        }
    }

    /// <summary>
    /// Boot/instance changes invalidate ALL mappings. Never reuse old serials
    /// across restarts, even if an old server assigns the same uint32 value.
    /// </summary>
    internal void ResetForNativeServerRestart(Guid freshServerEpoch)
    {
        if (freshServerEpoch == Guid.Empty)
            throw new ArgumentException("New epoch required.");

        lock (_sync)
        {
            if (freshServerEpoch == _serverEpoch)
                throw new ArgumentException("Restart requires a new epoch.");
            _serverEpoch = freshServerEpoch;
            _byNative.Clear();
            _byMobile.Clear();
            _bySession.Clear();
        }
    }

    internal int BoundCount
    {
        get { lock (_sync) return _bySession.Count; }
    }
}
